import type { Profile, SocialLink, Job, SkillGroup, SchoolEntry } from "@/lib/data";

/**
 * Shared clean, single-column, black-on-white résumé body. Used by:
 *  - <PrintResume> — the always-current résumé, hidden on screen and revealed
 *    only when printing to PDF.
 *  - the admin "tailored résumé" viewer (/admin/tailored/[id]) — a saved,
 *    job-specific variant generated by the tailoring tool, shown directly on
 *    screen and also printable.
 *
 * Content (summary/skills order/experience highlights) is passed in rather
 * than read from `profile.tagline` etc. directly, so a tailored variant can
 * override just those without duplicating this markup.
 */
export interface ResumeDocumentProps {
  profile: Profile;
  socials: SocialLink[];
  skills: SkillGroup[];
  experience: Job[];
  education: SchoolEntry[];
  /** Intro summary paragraph — defaults to `profile.tagline` for the live résumé. */
  summary: string;
}

/** Web links print as a readable bare URL; everything else (tel:) as the handle. */
function contactText(s: SocialLink): string {
  return /^https?:\/\//.test(s.href)
    ? s.href.replace(/^https?:\/\/(www\.)?/, "").replace(/\/$/, "")
    : s.handle;
}

export default function ResumeDocument({
  profile,
  socials,
  skills,
  experience,
  education,
  summary,
}: ResumeDocumentProps) {
  return (
    <>
      {/* Header */}
      <header className="border-b border-black pb-2">
        <h1 className="font-mono text-2xl font-bold">{profile.name}</h1>
        <p className="text-base">{profile.title}</p>
        <p className="mt-1 text-xs">
          <a href={`mailto:${profile.email}`}>{profile.email}</a>
          {socials.map((s) => (
            <span key={s.label}>
              {" · "}
              <a href={s.href}>{contactText(s)}</a>
            </span>
          ))}
          {` · ${profile.location}`}
        </p>
        <p className="mt-1 text-xs">
          Full résumé, projects, and an interactive terminal at{" "}
          <a href={`https://${profile.host}`} className="font-semibold">
            {profile.host}
          </a>
        </p>
      </header>

      {/* Summary */}
      <section className="mt-2">
        <p className="text-sm">{summary}</p>
      </section>

      {/* Skills */}
      <section className="mt-2">
        <h2 className="border-b border-black/30 text-sm font-bold uppercase tracking-wide">
          Skills
        </h2>
        <ul className="mt-1 text-sm">
          {skills.map((g) => (
            <li key={g.label}>
              <span className="font-semibold">{g.label}:</span>{" "}
              {g.items.join(", ")}
            </li>
          ))}
        </ul>
      </section>

      {/* Experience */}
      <section className="print-break mt-2">
        <h2 className="border-b border-black/30 text-sm font-bold uppercase tracking-wide">
          Experience
        </h2>
        {experience.map((j) => (
          <div key={j.company + j.role} className="print-break mt-1.5 text-sm">
            <div className="flex justify-between gap-4">
              <span className="font-semibold">
                {j.role} — {j.company}
              </span>
              <span className="whitespace-nowrap">{j.period}</span>
            </div>
            <p className="text-xs italic">
              {j.location} · {j.summary}
            </p>
            <ul className="ml-4 list-disc">
              {j.highlights.map((h, i) => (
                <li key={i}>{h.text}</li>
              ))}
            </ul>
          </div>
        ))}
      </section>

      {/* Education */}
      <section className="print-break mt-2">
        <h2 className="border-b border-black/30 text-sm font-bold uppercase tracking-wide">
          Education
        </h2>
        {education.map((e) => (
          <div key={e.school} className="mt-1 flex justify-between text-sm">
            <span>
              <span className="font-semibold">{e.credential}</span> — {e.school}
            </span>
            <span>{e.period}</span>
          </div>
        ))}
      </section>
    </>
  );
}
